    "GDN": {
        "pure":  f"{BASE_CLEAN}/exp007/1.3b/GDN-pure/samples/lambada_openai.jsonl",
        "h24-1": f"{BASE_CLEAN}/1.3b/GDN-h24-1-logsamples/samples/lambada_openai.jsonl",
