        "h12-1": f"{BASE_CLEAN}/exp007/1.3b/RetNet-h12-1/samples/lambada_openai.jsonl",
        "h6-1":  f"{BASE_CLEAN}/exp007/1.3b/RetNet-h6-1/samples/lambada_openai.jsonl",
