        lo, hi = bin_edges[i], bin_edges[i + 1]
        if i == n_bins - 1:
            mask = (confidences >= lo) & (confidences <= hi)
        else:
            mask = (confidences >= lo) & (confidences < hi)

        bin_count = mask.sum()
        if bin_count == 0:
            bin_details.append({"lo": round(lo, 4), "hi": round(hi, 4), "count": 0,
