        avg_acc = float(accuracies[mask].mean())
        gap = abs(avg_acc - avg_conf)

        weight = bin_count / n
        ece += weight * gap
        mce = max(mce, gap)

        bin_details.append({"lo": round(lo, 4), "hi": round(hi, 4), "count": int(bin_count),
                            "avg_conf": round(avg_conf, 6), "avg_acc": round(avg_acc, 6),
                            "gap": round(gap, 6)})

    return float(ece), float(mce), bin_details


